class Solution:
    def singleDivisorTriplet(self, nums):
        from collections import Counter
        cnt = Counter(nums)
        vals = sorted(cnt)
        ans = 0
        for i, a in enumerate(vals):
            for b in vals[i:]:
                for c in vals[vals.index(b):]:
                    s = a + b + c
                    d = (s % a == 0) + (s % b == 0) + (s % c == 0)
                    if d != 1:
                        continue
                    if a == b == c:
                        continue
                    mult = 3 if (a == b or b == c or a == c) else 6
                    ans += cnt[a] * cnt[b] * cnt[c] * mult
        return ans

