class Solution {
public:
    long long singleDivisorTriplet(vector<int>& nums) {
        long long cnt[101] = {};
        for (int x : nums) cnt[x]++;
        long long ans = 0;
        for (int a = 1; a <= 100; a++) {
            if (!cnt[a]) continue;
            for (int b = a; b <= 100; b++) {
                if (!cnt[b]) continue;
                for (int c = b; c <= 100; c++) {
                    if (!cnt[c]) continue;
                    int s = a + b + c;
                    int d = (s % a == 0) + (s % b == 0) + (s % c == 0);
                    if (d != 1 || (a == b && b == c)) continue;
                    long long m = (a == b || b == c || a == c) ? 3 : 6;
                    ans += cnt[a] * cnt[b] * cnt[c] * m;
                }
            }
        }
        return ans;
    }
};

