var singleDivisorTriplet = function(nums) {
    const cnt = Array(101).fill(0);
    for (const x of nums) cnt[x]++;
    let ans = 0;
    for (let a = 1; a <= 100; a++) {
        if (!cnt[a]) continue;
        for (let b = a; b <= 100; b++) {
            if (!cnt[b]) continue;
            for (let c = b; c <= 100; c++) {
                if (!cnt[c]) continue;
                const s = a + b + c;
                const d = (s % a === 0) + (s % b === 0) + (s % c === 0);
                if (d !== 1 || (a === b && b === c)) continue;
                const m = (a === b || b === c || a === c) ? 3 : 6;
                ans += cnt[a] * cnt[b] * cnt[c] * m;
            }
        }
    }
    return ans;
};
